/** The payment card to use to fund a payment. Can be a credit or debit card.Note: Passing card number, cvv and expiry directly via the API requires PCI SAQ D compliance. *PayPal offers a mechanism by which you do not have to take on the PCI SAQ D burden by using hosted fields - refer to this… */
export type PaypalCheckoutCardRequestInput = Record<string, PaypalJsonValue>;

/** The intent to either capture payment immediately or authorize a payment for an order after order creation. */
export type PaypalCheckoutCheckoutPaymentIntentInput = 'CAPTURE' | 'AUTHORIZE';

/** A Globally Unique Identifier (GUID) value. */
export type PaypalCheckoutGuidInput = string;

/** Reference values used by the card network to identify a transaction. */
export type PaypalCheckoutNetworkTransactionReferenceInput = Record<
	string,
	PaypalJsonValue
>;

/** Customizes the payer confirmation experience. */
export type PaypalCheckoutOrderConfirmApplicationContextInput = {
	/** Label to present to your payer as part of the PayPal hosted web experience. */
	brand_name?: string;
	locale?: PaypalJsonValue;
	/** The URL where the customer is redirected after the customer approves the payment. */
	return_url?: string;
	/** The URL where the customer is redirected after the customer cancels the payment. */
	cancel_url?: string;
	stored_payment_source?: PaypalCheckoutStoredPaymentSourceInput;
};

/** An array of JSON patch objects to apply partial updates to resources. */
export type PaypalCheckoutPatchRequestInput = Array<PaypalJsonValue>;

/** The person or party who initiated or triggered the payment. */
export type PaypalCheckoutPaymentInitiatorInput = 'CUSTOMER' | 'MERCHANT';

/** The payment source definition. */
export type PaypalCheckoutPaymentSourceInput = {
	card?: PaypalCheckoutCardRequestInput;
	token?: PaypalCheckoutTokenInput;
	paypal?: PaypalJsonValue;
	bancontact?: PaypalJsonValue;
	blik?: PaypalJsonValue;
	eps?: PaypalJsonValue;
	giropay?: PaypalJsonValue;
	ideal?: PaypalJsonValue;
	mybank?: PaypalJsonValue;
	p24?: PaypalJsonValue;
	sofort?: PaypalJsonValue;
	trustly?: PaypalJsonValue;
	apple_pay?: PaypalJsonValue;
	google_pay?: PaypalJsonValue;
	venmo?: PaypalJsonValue;
	crypto?: PaypalJsonValue;
};

