/** The stand-alone date, in [Internet date and time format](https://tools.ietf.org/html/rfc3339#section-5.6). To represent special legal values, such as a date of birth, you should use dates with no associated time or time-zone data. Whenever possible, use the standard `date_time` type. This… */
export type PaypalTrackingDateNoTimeInput = string;

/** The date and time, in [Internet date and time format](https://tools.ietf.org/html/rfc3339#section-5.6). Seconds are required while fractional seconds are optional.Note: The regular expression provides guidance but does not reject all invalid dates. */
export type PaypalTrackingDateTimeInput = string;

/** A request-related [HATEOAS link](/api/rest/responses/#hateoas-links). */
export type PaypalTrackingLinkDescriptionInput = {
	/** The complete target URL. To make the related call, combine the method with this link, in [URI template format](https://tools.ietf.org/html/rfc6570). Include the `$`, `(`, and `)` characters for pre-processing. The `href` is the key HATEOAS component that links a completed call with a subsequent… */
	href: string;
	/** The [link relation type](https://tools.ietf.org/html/rfc5988#section-4), which serves as an ID for a link that unambiguously describes the semantics of the link. See [Link Relations](https://www.iana.org/assignments/link-relations/link-relations.xhtml). */
	rel: string;
	/** The HTTP method required to make the related call. */
	method?:
		| 'GET'
		| 'POST'
		| 'PUT'
		| 'DELETE'
		| 'HEAD'
		| 'CONNECT'
		| 'OPTIONS'
		| 'PATCH';
};

/** An array of request-related [HATEOAS links](/docs/api/reference/api-responses/#hateoas-links). */
export type PaypalTrackingLinkDescriptionListInput =
	Array<PaypalTrackingLinkDescriptionInput>;

/** The tracking information for a shipment. */
export type PaypalTrackingTrackerInput = {
	/** The PayPal transaction ID. */
	transaction_id: string;
	/** The tracking number for the shipment. Carrier information, `carrier` is required if tracking_number is provided. */
	tracking_number?: string;
	/** The type of tracking number. */
	tracking_number_type?: PaypalTrackingTrackingNumberTypeInput;
	status: PaypalTrackingTrackingStatusInput;
	/** The date when the shipment occurred, in [Internet date and time format](https://tools.ietf.org/html/rfc3339#section-5.6). */
	shipment_date?: PaypalTrackingDateNoTimeInput;
	carrier?: PaypalTrackingCarrierInput;
	/** The name of the carrier for the shipment. Provide this value only if the carrier parameter is OTHER. */
	carrier_name_other?: string;
	/** If true , sends an email notification to the buyer of the PayPal transaction. The email contains the tracking information that was uploaded through the API. */
	notify_buyer?: boolean;
	/** The date and time when the tracking information was last updated, in [Internet date and time format](https://tools.ietf.org/html/rfc3339#section-5.6). */
	last_updated_time?: PaypalTrackingDateTimeInput;
	/** To denote whether the shipment is sent forward to the receiver or returned back. */
	shipment_direction?: 'FORWARD' | 'RETURN';
	/** Tracking Link of the shipment. */
	tracking_url?: string;
	links?: PaypalTrackingLinkDescriptionListInput;
};

